package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClientIdTokenSignedResponseAlgOptions;

class IdTokenSignedResponseAlgVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property id token signed response alg of oauth client ")
  void test_id_token_signed_response_alg_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class,
        () -> IdTokenSignedResponseAlgVO.tryFrom("_RS256_"));
    Assertions.assertEquals(OauthClientIdTokenSignedResponseAlgOptions.RS256,
        IdTokenSignedResponseAlgVO.tryFrom("RS256").getIdTokenSignedResponseAlg().orElse(null));
    Assertions.assertFalse(
        IdTokenSignedResponseAlgVO.nullValue().getIdTokenSignedResponseAlg().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        IdTokenSignedResponseAlgVO.tryFrom(null).getIdTokenSignedResponseAlg().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(OauthClientIdTokenSignedResponseAlgOptions.RS256,
        IdTokenSignedResponseAlgVO.from(OauthClientIdTokenSignedResponseAlgOptions.RS256)
            .getIdTokenSignedResponseAlg().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> IdTokenSignedResponseAlgVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + OauthClientIdTokenSignedResponseAlgOptions.RS256 + "]",
        IdTokenSignedResponseAlgVO.from(OauthClientIdTokenSignedResponseAlgOptions.RS256)
            .toString());
  }
}
